        main = v.split('+', 1)[0]
        if '-' in main:
            core, prerelease = main.split('-', 1)
            has_prerelease = 0
        else:
            core = main
            prerelease = None
            has_prerelease = 1

        parts = core.split('.')
        major, minor, patch = (int(p) for p in parts[:3])

        if prerelease is not None:
